ROOT = Path(__file__).resolve().parents[1] / "references/education-stage-starters.json"
SRC23 = "Double6 自编二升三通用题（未对齐指定教材）"
SRC34 = "Double6 自编三升四通用题（未对齐指定教材）"


def q(
    item_id: str,
    title: str,
    prompt: str,
    answer: str,
    explanation: str,
    knowledge_point: str,
    source: str,
    options: list[str] | None = None,
    input_type: str | None = None,
    mission: str = "",
    story: str = "",
) -> dict:
    row = {
        "kind": "question",
        "item_id": item_id,
        "title": title,
        "prompt": prompt,
        "answer": str(answer),
        "explanation": explanation,
        "knowledge_point": knowledge_point,
        "difficulty": "基础",
        "source_label": source,
    }
    if options:
        row["options"] = options
    if input_type:
        row["input_type"] = input_type
    if mission:
        row["mission"] = mission
    if story:
        row["story"] = story
    return row


def plus(item_id: str, a: int, b: int, source: str, point: str, title: str) -> dict:
    return q(item_id, title, f"{a} + {b} 等于多少？", a + b, f"{a}+{b}={a+b}。", point, source, input_type="number")


def minus(item_id: str, a: int, b: int, source: str, point: str, title: str) -> dict:
    return q(item_id, title, f"{a} - {b} 等于多少？", a - b, f"{a}-{b}={a-b}。", point, source, input_type="number")


def mul(item_id: str, a: int, b: int, source: str, point: str, title: str) -> dict:
    return q(item_id, title, f"{a} × {b} 等于多少？", a * b, f"{a}×{b}={a*b}。", point, source, input_type="number")


def div(item_id: str, a: int, b: int, source: str, point: str, title: str) -> dict:
    return q(item_id, title, f"{a} ÷ {b} 等于多少？", a // b, f"因为 {b}×{a//b}={a}，所以 {a}÷{b}={a//b}。", point, source, input_type="number")


