    data = json.loads(ROOT.read_text(encoding="utf-8"))
    extras_by_stage = {
        "primary-transition-2-to-3": EXTRAS["primary-transition-2-to-3"],
        "primary-transition-3-to-4": extras_34(),
    }
    for stage in data["stages"]:
        extras = extras_by_stage.get(stage["stage_id"])
        if not extras:
            continue
        for module_id, rows in extras.items():
            existing = {item["item_id"] for item in stage["modules"][module_id]}
            for row in rows:
                if row["item_id"] not in existing:
                    stage["modules"][module_id].append(row)
                    existing.add(row["item_id"])
    ROOT.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
