    for stage in data["stages"]:
        if stage["stage_id"] not in extras_by_stage:
            continue
        print("==", stage["stage_id"])
        for module_id, items in stage["modules"].items():
            if module_id == "education-errors":
                continue
            counts = Counter(item["knowledge_point"] for item in items)
            print(module_id, len(items), dict(counts))


